class Supply extends DataClass implements Insertable<Supply> {
  final String id;
  final String businessId;
  final String name;
  final String? brand;
  final double? unitQuantity;
  final String? unit;
  final String? lastStoreName;
  final String? lastStoreAddress;
  final int currentPrice;
  final String? notes;
  final bool isActive;
  final DateTime createdAt;
  final DateTime updatedAt;
  final double currentStock;
  final double minimumStock;
  final double maximumStock;
  final double? lowStockThreshold;
  final String stockUnit;
  final String? purchaseUnit;
  final double unitsPerPurchase;
  final double costPerBaseUnit;

  /// Internal item code / SKU. Normalised to upper-case by
  /// SupplyCatalogService. Unique per business when present.
  final String? sku;

  /// Scanned barcode (EAN/UPC/QR payload). Unique per business when
  /// present.
  final String? barcode;

  /// Reuses the same per-business category list as products, so a
  /// category like "Dairy" works for both a raw supply and a
  /// finished item without maintaining two separate lists.
  final String? categoryId;

  /// True when this supply is priced by variable weight (produce, meat,
  /// bulk bins) — the purchase unit itself IS a weight unit (g/kg), so
  /// the amount bought is a free-form decimal entered per purchase
  /// (0.5 kg, 1.25 kg), not a fixed pack size.
  final bool isSoldByWeight;

  /// Local file path for the item photo — reference only, not bytes.
  final String? imagePath;

  /// Manual display order in the price catalog.
  final int sortOrder;
  const Supply({
    required this.id,
    required this.businessId,
    required this.name,
    this.brand,
    this.unitQuantity,
    this.unit,
    this.lastStoreName,
    this.lastStoreAddress,
    required this.currentPrice,
    this.notes,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
    required this.currentStock,
    required this.minimumStock,
    required this.maximumStock,
    this.lowStockThreshold,
    required this.stockUnit,
    this.purchaseUnit,
    required this.unitsPerPurchase,
    required this.costPerBaseUnit,
    this.sku,
    this.barcode,
    this.categoryId,
    required this.isSoldByWeight,
    this.imagePath,
    required this.sortOrder,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || brand != null) {
      map['brand'] = Variable<String>(brand);
    }
    if (!nullToAbsent || unitQuantity != null) {
      map['unit_quantity'] = Variable<double>(unitQuantity);
    }
    if (!nullToAbsent || unit != null) {
      map['unit'] = Variable<String>(unit);
    }
    if (!nullToAbsent || lastStoreName != null) {
      map['last_store_name'] = Variable<String>(lastStoreName);
    }
    if (!nullToAbsent || lastStoreAddress != null) {
      map['last_store_address'] = Variable<String>(lastStoreAddress);
    }
    map['current_price'] = Variable<int>(currentPrice);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['current_stock'] = Variable<double>(currentStock);
    map['minimum_stock'] = Variable<double>(minimumStock);
    map['maximum_stock'] = Variable<double>(maximumStock);
    if (!nullToAbsent || lowStockThreshold != null) {
      map['low_stock_threshold'] = Variable<double>(lowStockThreshold);
    }
    map['stock_unit'] = Variable<String>(stockUnit);
    if (!nullToAbsent || purchaseUnit != null) {
      map['purchase_unit'] = Variable<String>(purchaseUnit);
    }
    map['units_per_purchase'] = Variable<double>(unitsPerPurchase);
    map['cost_per_base_unit'] = Variable<double>(costPerBaseUnit);
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    map['is_sold_by_weight'] = Variable<bool>(isSoldByWeight);
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    return map;
  }

  SuppliesCompanion toCompanion(bool nullToAbsent) {
    return SuppliesCompanion(
      id: Value(id),
      businessId: Value(businessId),
      name: Value(name),
      brand: brand == null && nullToAbsent
          ? const Value.absent()
          : Value(brand),
      unitQuantity: unitQuantity == null && nullToAbsent
          ? const Value.absent()
          : Value(unitQuantity),
      unit: unit == null && nullToAbsent ? const Value.absent() : Value(unit),
      lastStoreName: lastStoreName == null && nullToAbsent
          ? const Value.absent()
