    map['store_name'] = Variable<String>(storeName);
    if (!nullToAbsent || storeAddress != null) {
      map['store_address'] = Variable<String>(storeAddress);
    }
    if (!nullToAbsent || supplierId != null) {
      map['supplier_id'] = Variable<String>(supplierId);
    }
    map['recorded_date'] = Variable<DateTime>(recordedDate);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['purchase_quantity'] = Variable<double>(purchaseQuantity);
    map['units_per_purchase_at_time'] = Variable<double>(
      unitsPerPurchaseAtTime,
    );
    if (!nullToAbsent || shoppingCartItemId != null) {
      map['shopping_cart_item_id'] = Variable<String>(shoppingCartItemId);
    }
    return map;
  }

