class Product extends DataClass implements Insertable<Product> {
  final String id;
  final String businessId;
  final String name;

  /// Internal product code / SKU. Normalised to upper-case by
  /// ProductCatalogService. Unique per business when present —
  /// enforced by a partial unique index (NULLs stay distinct).
  final String? sku;

  /// Scanned barcode (EAN/UPC/QR payload). Unique per business when
  /// present, same partial-index treatment as [sku].
  final String? barcode;
  final String? categoryId;

  /// Longer description / prep notes shown on the product detail page.
  final String? description;

  /// Local file path or asset reference for the product photo. Stored
  /// as a reference only — the bytes live on disk, not in SQLite.
  final String? imagePath;

  /// 'finished' | 'intermediate' | 'merchandise' | 'service'
  final String productType;

  /// 'recipe' | 'stocked' | 'non_stocked'
  final String trackingType;

  /// The unit this product is produced/sold in — "cup", "serving",
  /// "piece", "bottle", etc. This is what recipe yields and sale
  /// quantities are expressed in.
  final String unit;
  final int? sellPrice;

  /// On-hand quantity for trackingType == 'stocked' (merchandise you
  /// buy and resell as-is). Ignored for recipe/non-stocked products,
  /// whose availability is derived from supply stock instead.
  final double currentStock;
  final double? lowStockThreshold;

  /// False for intermediate-only components (e.g. "Espresso Base")
  /// that exist purely to be used inside other recipes and are never
  /// sold directly to a customer. Preserved as-is: every existing
  /// query on isSellable keeps working.
  final bool isSellable;
  final bool isActive;

  /// Manual display order inside the catalog / POS grid.
  final int sortOrder;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Product({
    required this.id,
    required this.businessId,
    required this.name,
    this.sku,
    this.barcode,
    this.categoryId,
    this.description,
    this.imagePath,
    required this.productType,
    required this.trackingType,
    required this.unit,
    this.sellPrice,
    required this.currentStock,
    this.lowStockThreshold,
    required this.isSellable,
    required this.isActive,
    required this.sortOrder,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['product_type'] = Variable<String>(productType);
    map['tracking_type'] = Variable<String>(trackingType);
    map['unit'] = Variable<String>(unit);
    if (!nullToAbsent || sellPrice != null) {
      map['sell_price'] = Variable<int>(sellPrice);
    }
    map['current_stock'] = Variable<double>(currentStock);
    if (!nullToAbsent || lowStockThreshold != null) {
      map['low_stock_threshold'] = Variable<double>(lowStockThreshold);
    }
    map['is_sellable'] = Variable<bool>(isSellable);
    map['is_active'] = Variable<bool>(isActive);
    map['sort_order'] = Variable<int>(sortOrder);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      businessId: Value(businessId),
      name: Value(name),
      sku: sku == null && nullToAbsent ? const Value.absent() : Value(sku),
      barcode: barcode == null && nullToAbsent
          ? const Value.absent()
          : Value(barcode),
      categoryId: categoryId == null && nullToAbsent
          ? const Value.absent()
          : Value(categoryId),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      imagePath: imagePath == null && nullToAbsent
          ? const Value.absent()
          : Value(imagePath),
      productType: Value(productType),
      trackingType: Value(trackingType),
      unit: Value(unit),
      sellPrice: sellPrice == null && nullToAbsent
          ? const Value.absent()
          : Value(sellPrice),
      currentStock: Value(currentStock),
      lowStockThreshold: lowStockThreshold == null && nullToAbsent
          ? const Value.absent()
          : Value(lowStockThreshold),
      isSellable: Value(isSellable),
      isActive: Value(isActive),
      sortOrder: Value(sortOrder),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Product.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Product(
      id: serializer.fromJson<String>(json['id']),
      businessId: serializer.fromJson<String>(json['businessId']),
      name: serializer.fromJson<String>(json['name']),
      sku: serializer.fromJson<String?>(json['sku']),
      barcode: serializer.fromJson<String?>(json['barcode']),
      categoryId: serializer.fromJson<String?>(json['categoryId']),
      description: serializer.fromJson<String?>(json['description']),
      imagePath: serializer.fromJson<String?>(json['imagePath']),
      productType: serializer.fromJson<String>(json['productType']),
      trackingType: serializer.fromJson<String>(json['trackingType']),
      unit: serializer.fromJson<String>(json['unit']),
      sellPrice: serializer.fromJson<int?>(json['sellPrice']),
      currentStock: serializer.fromJson<double>(json['currentStock']),
      lowStockThreshold: serializer.fromJson<double?>(
        json['lowStockThreshold'],
      ),
      isSellable: serializer.fromJson<bool>(json['isSellable']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'businessId': serializer.toJson<String>(businessId),
      'name': serializer.toJson<String>(name),
      'sku': serializer.toJson<String?>(sku),
      'barcode': serializer.toJson<String?>(barcode),
      'categoryId': serializer.toJson<String?>(categoryId),
      'description': serializer.toJson<String?>(description),
      'imagePath': serializer.toJson<String?>(imagePath),
      'productType': serializer.toJson<String>(productType),
      'trackingType': serializer.toJson<String>(trackingType),
      'unit': serializer.toJson<String>(unit),
      'sellPrice': serializer.toJson<int?>(sellPrice),
      'currentStock': serializer.toJson<double>(currentStock),
      'lowStockThreshold': serializer.toJson<double?>(lowStockThreshold),
      'isSellable': serializer.toJson<bool>(isSellable),
      'isActive': serializer.toJson<bool>(isActive),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Product copyWith({
    String? id,
    String? businessId,
    String? name,
    Value<String?> sku = const Value.absent(),
    Value<String?> barcode = const Value.absent(),
    Value<String?> categoryId = const Value.absent(),
    Value<String?> description = const Value.absent(),
    Value<String?> imagePath = const Value.absent(),
    String? productType,
    String? trackingType,
    String? unit,
    Value<int?> sellPrice = const Value.absent(),
    double? currentStock,
    Value<double?> lowStockThreshold = const Value.absent(),
    bool? isSellable,
    bool? isActive,
    int? sortOrder,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Product(
    id: id ?? this.id,
    businessId: businessId ?? this.businessId,
    name: name ?? this.name,
    sku: sku.present ? sku.value : this.sku,
    barcode: barcode.present ? barcode.value : this.barcode,
    categoryId: categoryId.present ? categoryId.value : this.categoryId,
    description: description.present ? description.value : this.description,
    imagePath: imagePath.present ? imagePath.value : this.imagePath,
    productType: productType ?? this.productType,
    trackingType: trackingType ?? this.trackingType,
    unit: unit ?? this.unit,
    sellPrice: sellPrice.present ? sellPrice.value : this.sellPrice,
    currentStock: currentStock ?? this.currentStock,
    lowStockThreshold: lowStockThreshold.present
        ? lowStockThreshold.value
        : this.lowStockThreshold,
    isSellable: isSellable ?? this.isSellable,
    isActive: isActive ?? this.isActive,
    sortOrder: sortOrder ?? this.sortOrder,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Product copyWithCompanion(ProductsCompanion data) {
    return Product(
      id: data.id.present ? data.id.value : this.id,
      businessId: data.businessId.present
          ? data.businessId.value
          : this.businessId,
      name: data.name.present ? data.name.value : this.name,
      sku: data.sku.present ? data.sku.value : this.sku,
      barcode: data.barcode.present ? data.barcode.value : this.barcode,
      categoryId: data.categoryId.present
          ? data.categoryId.value
          : this.categoryId,
      description: data.description.present
          ? data.description.value
          : this.description,
      imagePath: data.imagePath.present ? data.imagePath.value : this.imagePath,
      productType: data.productType.present
          ? data.productType.value
          : this.productType,
      trackingType: data.trackingType.present
          ? data.trackingType.value
          : this.trackingType,
      unit: data.unit.present ? data.unit.value : this.unit,
      sellPrice: data.sellPrice.present ? data.sellPrice.value : this.sellPrice,
      currentStock: data.currentStock.present
          ? data.currentStock.value
          : this.currentStock,
      lowStockThreshold: data.lowStockThreshold.present
          ? data.lowStockThreshold.value
          : this.lowStockThreshold,
      isSellable: data.isSellable.present
          ? data.isSellable.value
          : this.isSellable,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      sortOrder: data.sortOrder.present ? data.sortOrder.value : this.sortOrder,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Product(')
          ..write('id: $id, ')
          ..write('businessId: $businessId, ')
          ..write('name: $name, ')
          ..write('sku: $sku, ')
          ..write('barcode: $barcode, ')
          ..write('categoryId: $categoryId, ')
          ..write('description: $description, ')
          ..write('imagePath: $imagePath, ')
          ..write('productType: $productType, ')
          ..write('trackingType: $trackingType, ')
          ..write('unit: $unit, ')
          ..write('sellPrice: $sellPrice, ')
          ..write('currentStock: $currentStock, ')
          ..write('lowStockThreshold: $lowStockThreshold, ')
          ..write('isSellable: $isSellable, ')
          ..write('isActive: $isActive, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    businessId,
    name,
    sku,
    barcode,
    categoryId,
    description,
    imagePath,
    productType,
    trackingType,
    unit,
    sellPrice,
    currentStock,
    lowStockThreshold,
    isSellable,
    isActive,
    sortOrder,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Product &&
          other.id == this.id &&
          other.businessId == this.businessId &&
          other.name == this.name &&
          other.sku == this.sku &&
          other.barcode == this.barcode &&
          other.categoryId == this.categoryId &&
          other.description == this.description &&
          other.imagePath == this.imagePath &&
          other.productType == this.productType &&
          other.trackingType == this.trackingType &&
          other.unit == this.unit &&
          other.sellPrice == this.sellPrice &&
          other.currentStock == this.currentStock &&
          other.lowStockThreshold == this.lowStockThreshold &&
          other.isSellable == this.isSellable &&
          other.isActive == this.isActive &&
          other.sortOrder == this.sortOrder &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

