class InventoryMovement extends DataClass
    implements Insertable<InventoryMovement> {
  final String id;
  final String supplyId;
  final String? branchId;

  /// 'production_consumption' | 'manual_adjustment' | 'restock'
  final String movementType;
  final String unit;
  final double quantity;
  final String? referenceType;
  final String? referenceId;
  final DateTime movementDate;
  final String? notes;

  /// Same purpose as SupplyPriceHistory.shoppingCartItemId — lets a
  /// checkout deletion find and remove the exact 'restock' movement it
  /// created, instead of matching by value (which can collide).
  final String? shoppingCartItemId;
  const InventoryMovement({
    required this.id,
    required this.supplyId,
    this.branchId,
    required this.movementType,
    required this.unit,
    required this.quantity,
    this.referenceType,
    this.referenceId,
    required this.movementDate,
    this.notes,
    this.shoppingCartItemId,
  });
