    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['supply_id'] = Variable<String>(supplyId);
    if (!nullToAbsent || branchId != null) {
      map['branch_id'] = Variable<String>(branchId);
    }
    map['movement_type'] = Variable<String>(movementType);
    map['unit'] = Variable<String>(unit);
    map['quantity'] = Variable<double>(quantity);
    if (!nullToAbsent || referenceType != null) {
      map['reference_type'] = Variable<String>(referenceType);
    }
    if (!nullToAbsent || referenceId != null) {
      map['reference_id'] = Variable<String>(referenceId);
    }
    map['movement_date'] = Variable<DateTime>(movementDate);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || shoppingCartItemId != null) {
      map['shopping_cart_item_id'] = Variable<String>(shoppingCartItemId);
    }
    return map;
  }

  InventoryMovementsCompanion toCompanion(bool nullToAbsent) {
    return InventoryMovementsCompanion(
      id: Value(id),
      supplyId: Value(supplyId),
      branchId: branchId == null && nullToAbsent
          ? const Value.absent()
          : Value(branchId),
      movementType: Value(movementType),
      unit: Value(unit),
      quantity: Value(quantity),
      referenceType: referenceType == null && nullToAbsent
          ? const Value.absent()
          : Value(referenceType),
      referenceId: referenceId == null && nullToAbsent
          ? const Value.absent()
          : Value(referenceId),
      movementDate: Value(movementDate),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      shoppingCartItemId: shoppingCartItemId == null && nullToAbsent
          ? const Value.absent()
          : Value(shoppingCartItemId),
    );
