class PosSale extends DataClass implements Insertable<PosSale> {
  final String id;
  final String businessId;
  final String? branchId;
  final DateTime saleDate;
  final int totalAmount;
  final bool isStockOnly;
  final String? paymentAccountId;
  final String? notes;
  final String? sessionId;
  final bool isVoided;
  final DateTime? voidedAt;
  final String? voidReason;
  final String? cashierUserId;
  final String? cashierName;

  /// Discount in centavos. totalAmount is stored NET of this.
  final int discountAmount;
  final String? discountLabel;

  /// Human receipt number, e.g. "A1B2-007" (shift code + running number).
  final String? receiptNo;

  /// Customer a credit sale was charged to (null for ordinary sales).
  final String? customerId;

  /// Dine in / Take out / GrabFood... A text snapshot, so renaming a type
  /// later never changes old receipts.
  final String? orderType;

  /// Platform / online order number (GrabFood, Foodpanda, Shopee...).
  final String? orderRef;
  final String? contactName;
  final String? contactPhone;
  final String? deliveryAddress;

  /// Table name at the time of the sale (a snapshot, like orderType).
  final String? tableLabel;
  final int? guests;
  final DateTime createdAt;
  const PosSale({
    required this.id,
    required this.businessId,
    this.branchId,
    required this.saleDate,
    required this.totalAmount,
    required this.isStockOnly,
    this.paymentAccountId,
    this.notes,
    this.sessionId,
    required this.isVoided,
    this.voidedAt,
    this.voidReason,
    this.cashierUserId,
    this.cashierName,
    required this.discountAmount,
    this.discountLabel,
    this.receiptNo,
    this.customerId,
    this.orderType,
    this.orderRef,
    this.contactName,
    this.contactPhone,
    this.deliveryAddress,
    this.tableLabel,
    this.guests,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['business_id'] = Variable<String>(businessId);
    if (!nullToAbsent || branchId != null) {
      map['branch_id'] = Variable<String>(branchId);
    }
    map['sale_date'] = Variable<DateTime>(saleDate);
    map['total_amount'] = Variable<int>(totalAmount);
    map['is_stock_only'] = Variable<bool>(isStockOnly);
    if (!nullToAbsent || paymentAccountId != null) {
      map['payment_account_id'] = Variable<String>(paymentAccountId);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || sessionId != null) {
      map['session_id'] = Variable<String>(sessionId);
    }
    map['is_voided'] = Variable<bool>(isVoided);
    if (!nullToAbsent || voidedAt != null) {
      map['voided_at'] = Variable<DateTime>(voidedAt);
    }
    if (!nullToAbsent || voidReason != null) {
      map['void_reason'] = Variable<String>(voidReason);
    }
    if (!nullToAbsent || cashierUserId != null) {
      map['cashier_user_id'] = Variable<String>(cashierUserId);
    }
    if (!nullToAbsent || cashierName != null) {
      map['cashier_name'] = Variable<String>(cashierName);
    }
    map['discount_amount'] = Variable<int>(discountAmount);
    if (!nullToAbsent || discountLabel != null) {
      map['discount_label'] = Variable<String>(discountLabel);
    }
    if (!nullToAbsent || receiptNo != null) {
      map['receipt_no'] = Variable<String>(receiptNo);
    }
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    if (!nullToAbsent || orderType != null) {
      map['order_type'] = Variable<String>(orderType);
    }
    if (!nullToAbsent || orderRef != null) {
      map['order_ref'] = Variable<String>(orderRef);
    }
    if (!nullToAbsent || contactName != null) {
      map['contact_name'] = Variable<String>(contactName);
    }
    if (!nullToAbsent || contactPhone != null) {
      map['contact_phone'] = Variable<String>(contactPhone);
    }
    if (!nullToAbsent || deliveryAddress != null) {
      map['delivery_address'] = Variable<String>(deliveryAddress);
    }
    if (!nullToAbsent || tableLabel != null) {
      map['table_label'] = Variable<String>(tableLabel);
    }
    if (!nullToAbsent || guests != null) {
      map['guests'] = Variable<int>(guests);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  PosSalesCompanion toCompanion(bool nullToAbsent) {
    return PosSalesCompanion(
      id: Value(id),
      businessId: Value(businessId),
      branchId: branchId == null && nullToAbsent
          ? const Value.absent()
          : Value(branchId),
      saleDate: Value(saleDate),
      totalAmount: Value(totalAmount),
      isStockOnly: Value(isStockOnly),
      paymentAccountId: paymentAccountId == null && nullToAbsent
          ? const Value.absent()
          : Value(paymentAccountId),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      sessionId: sessionId == null && nullToAbsent
          ? const Value.absent()
          : Value(sessionId),
      isVoided: Value(isVoided),
      voidedAt: voidedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(voidedAt),
      voidReason: voidReason == null && nullToAbsent
          ? const Value.absent()
          : Value(voidReason),
      cashierUserId: cashierUserId == null && nullToAbsent
          ? const Value.absent()
          : Value(cashierUserId),
      cashierName: cashierName == null && nullToAbsent
          ? const Value.absent()
          : Value(cashierName),
      discountAmount: Value(discountAmount),
      discountLabel: discountLabel == null && nullToAbsent
