class AppUser extends DataClass implements Insertable<AppUser> {
  final String id;
  final String email;
  final String passwordHash;
  final String passwordSalt;
  final String displayName;
  final DateTime createdAt;
  final DateTime? lastLoginAt;

  /// Salted hash of the owner/manager approval PIN. Device-local; never synced.
  final String? approvalPinHash;
  final String? approvalPinSalt;
  const AppUser({
    required this.id,
    required this.email,
    required this.passwordHash,
    required this.passwordSalt,
    required this.displayName,
    required this.createdAt,
    this.lastLoginAt,
    this.approvalPinHash,
    this.approvalPinSalt,
  });
