    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['email'] = Variable<String>(email);
    map['password_hash'] = Variable<String>(passwordHash);
    map['password_salt'] = Variable<String>(passwordSalt);
    map['display_name'] = Variable<String>(displayName);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || lastLoginAt != null) {
      map['last_login_at'] = Variable<DateTime>(lastLoginAt);
    }
    if (!nullToAbsent || approvalPinHash != null) {
      map['approval_pin_hash'] = Variable<String>(approvalPinHash);
    }
    if (!nullToAbsent || approvalPinSalt != null) {
      map['approval_pin_salt'] = Variable<String>(approvalPinSalt);
    }
    return map;
  }

  UsersCompanion toCompanion(bool nullToAbsent) {
    return UsersCompanion(
      id: Value(id),
      email: Value(email),
      passwordHash: Value(passwordHash),
      passwordSalt: Value(passwordSalt),
      displayName: Value(displayName),
      createdAt: Value(createdAt),
      lastLoginAt: lastLoginAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastLoginAt),
      approvalPinHash: approvalPinHash == null && nullToAbsent
          ? const Value.absent()
          : Value(approvalPinHash),
      approvalPinSalt: approvalPinSalt == null && nullToAbsent
          ? const Value.absent()
          : Value(approvalPinSalt),
    );
  }

